def schemas():
    common={'type':'string','enum':['UNKNOWN','NOT_REPORTED','NOT_APPLICABLE','UNCERTAIN']}
    experiment={'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'skill07-gold-experiment-v1','type':'object','required':['gold_experiment_id','benchmark_paper_id','paper_id','annotation_tier','review_state','experiment_title','experiment_role','experiment_granularity','biological_objects','intervention_or_design_action','trigger','conditions','implementation','controls','replicates','readouts','analysis','results','rationale','supported_alternatives','supported_rule','rule_scope','atomic_claim_ids','evidence_ids','critical_provenance','known_ambiguities','annotator_notes','created_by','created_at','updated_at','schema_version'],'properties':{'gold_experiment_id':{'type':'string','pattern':'^GOLD-P\\d{2}-E\\d{3}$'},'benchmark_paper_id':{'type':'string','pattern':'^GOLD-P\\d{2}$'},'paper_id':{'type':'string'},'annotation_tier':{'enum':['HUMAN_DRAFT','HUMAN_REVIEWED','ADJUDICATED_GOLD','FROZEN_GOLD']},'review_state':{'type':'string'},'experiment_title':{'type':'string'},'experiment_role':{'enum':['ENGINEERING_INTERVENTION','SCREENING','SELECTION','EVOLUTION','MEASUREMENT','CHARACTERIZATION','MECHANISTIC_VALIDATION','CAUSAL_VALIDATION','OPTIMIZATION','COMPARATIVE_VALIDATION','PRODUCTION_VALIDATION','OTHER','UNCERTAIN']},'experiment_granularity':{'enum':['ATOMIC_EXPERIMENT','EXPERIMENT_SERIES','CAMPAIGN','SUBEXPERIMENT','UNCERTAIN']},'parent_experiment_id':{'type':['string','null']},'iteration_or_stage':{},'relations':{'type':'array','items':{'type':'object','required':['relation','target_id'],'properties':{'relation':{'enum':['PART_OF','PRECEDES','FOLLOWS','ITERATION_OF','VALIDATES','MOTIVATES','COMPARES_WITH']},'target_id':{'type':'string'}}}},'biological_objects':{'type':'array','items':{'type':'object','required':['object_id','object_type','name','experimental_role'],'properties':{'object_id':{'type':'string'},'object_type':{'type':'string'},'name':{'type':'string'},'strain_or_host':{},'genotype':{},'construct':{},'parent_object':{},'experimental_role':{'type':'string'}}}},'intervention_or_design_action':{},'trigger':{},'conditions':{'type':'array'},'implementation':{},'controls':{'type':'array'},'replicates':{'type':'object'},'readouts':{'type':'array'},'analysis':{'type':'array'},'results':{'type':'array'},'rationale':{},'supported_alternatives':{'type':'array'},'supported_rule':{},'rule_scope':{},'atomic_claim_ids':{'type':'array','items':{'type':'string'}},'evidence_ids':{'type':'array','items':{'type':'string'}},'critical_provenance':{'type':'array'},'known_ambiguities':{'type':'array'},'annotator_notes':{'type':'string'},'created_by':{'type':'string'},'created_at':{'type':'string'},'updated_at':{'type':'string'},'schema_version':{'const':'1.0.0'},'origin_flags':{'type':'array'},'candidate_model_ids':{'type':'array'}},'additionalProperties':True}
    claim={'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'skill07-gold-claim-v1','type':'object','required':['claim_id','gold_experiment_id','claim_type','subject','predicate','object_or_value','qualifiers','claim_text_normalized','epistemic_status','value_role','support_status','evidence_ids','criticality','review_state','known_ambiguity','provenance','annotation_tier'],'properties':{'claim_id':{'type':'string','pattern':'^GOLD-P\\d{2}-E\\d{3}-C\\d{3}$'},'gold_experiment_id':{'type':'string'},'claim_type':{'enum':['OBJECT_IDENTITY','INTERVENTION','CONDITION','CONTROL','REPLICATE','READOUT','ANALYSIS','MEASURED_RESULT','COMPARATIVE_RESULT','CAUSAL_RESULT','RATIONALE','ALTERNATIVE','MECHANISTIC_INTERPRETATION','RULE','SCOPE','NEGATIVE_RESULT','LIMITATION']},'subject':{},'predicate':{},'object_or_value':{},'qualifiers':{'type':'object'},'claim_text_normalized':{'type':'string'},'epistemic_status':{'enum':['DIRECTLY_REPORTED','DERIVED_FROM_REPORTED_VALUES','AUTHOR_INTERPRETATION','REVIEWER_INTERPRETATION','INFERRED','UNCERTAIN']},'value_role':{'enum':['IMPLEMENTED','MEASURED','CALCULATED','REPORTED_REFERENCE','THRESHOLD','UNKNOWN']},'support_status':{'enum':['SUPPORTED','PARTIALLY_SUPPORTED','UNSUPPORTED','UNCERTAIN']},'evidence_ids':{'type':'array'},'criticality':{'enum':['CRITICAL','MAJOR','MINOR']},'review_state':{'type':'string'},'known_ambiguity':{},'provenance':{'type':'object'},'annotation_tier':{'enum':['HUMAN_DRAFT','HUMAN_REVIEWED','ADJUDICATED_GOLD','FROZEN_GOLD']}},'additionalProperties':True}
    evidence={'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'skill07-gold-evidence-v1','type':'object','required':['evidence_id','benchmark_paper_id','paper_id','source_document_id','source_attribution','anchor_text_or_fingerprint','quote_or_excerpt','evidence_scope','supports_claim_ids','support_type','support_strength','directness','resolution','availability','provenance','review_state','annotation_tier'],'properties':{'evidence_id':{'type':'string','pattern':'^GOLD-P\\d{2}-E\\d{3}-V\\d{3}$'},'benchmark_paper_id':{'type':'string'},'paper_id':{'type':'string'},'source_document_id':{'type':'string'},'source_attribution':{'type':'string'},'section':{},'paragraph_id':{},'page':{},'figure':{},'panel':{},'table':{},'supplement':{},'other_locator':{},'anchor_text_or_fingerprint':{'type':'string'},'quote_or_excerpt':{'type':'string','maxLength':500},'evidence_scope':{'enum':['TEXT_DIRECT','FIGURE','FIGURE_CAPTION','TABLE','METHODS','RESULTS','SUPPLEMENT','MULTI_ANCHOR']},'supports_claim_ids':{'type':'array'},'support_type':{'type':'string'},'support_strength':{'enum':['DIRECT','SUPPORTING_CONTEXT','INDIRECT','INSUFFICIENT']},'directness':{'type':'string'},'resolution':{'type':'string'},'availability':{'enum':['AVAILABLE','UNAVAILABLE','UNKNOWN']},'provenance':{'type':'object'},'review_state':{'type':'string'},'annotation_tier':{'enum':['HUMAN_DRAFT','HUMAN_REVIEWED','ADJUDICATED_GOLD','FROZEN_GOLD']}},'additionalProperties':True}
