def main(resume=True):
    schemas(); manifest=read(ROOT/'skill07_wave2_baseline_manifest.json'); byid={d['paper_id']:d for d in manifest['documents']}; gold=read(ROOT/'skill07_gold_review.json'); alignment=read(ROOT/'skill07_semantic_alignment_report.json')
    review_by={p['benchmark_paper_id']:p for p in gold['papers']}; imported=additional=0
    for i,pid in enumerate(EXPECTED,1):
        bid=f'GOLD-P{i:02d}'
        if pid not in byid:raise FileNotFoundError(f'fixed core source missing: {bid} {pid}')
        d=byid[pid]; source_path=Path(d['clean_document_path']); source=read(source_path); package=PACKAGES/bid
        if package.exists() and not resume:raise FileExistsError(package)
        package.mkdir(parents=True,exist_ok=True)
        paragraphs=[{'paragraph_id':p.get('paragraph_id'),'section':p.get('section'),'text':p.get('text',''),'fingerprint':hashlib.sha256(p.get('text','').encode()).hexdigest()[:16]} for p in source.get('paragraphs',[])]
        source_index={'benchmark_paper_id':bid,'paper_id':pid,'source_document_path':str(source_path),'source_document_hash':d['clean_document_hash'],'paragraph_ids':[p['paragraph_id'] for p in paragraphs],'paragraphs':paragraphs,'figures':source.get('figures',[]),'tables':source.get('tables',[]),'supplements':'UNAVAILABLE' if not any('supp' in str(s).casefold() for s in source.get('sections',[])) else 'REFERENCED_REVIEW_REQUIRED'}
        atomic_write(package/'source_index.json',source_index)
        review=review_by.get(bid,{}); aids=[]
        for item in gold.get('review_items',[]):
            if item['paper_benchmark_id']==bid:aids.append(item)
        pair=next((x for x in alignment['pairs'] if x['paper_id']==pid),None)
        imported+=len(pair['differences']) if pair else 0
        candidates=[]
        for item in aids:
            for origin,key in [('A_ONLY','a_interpretation'),('G_ONLY','g_interpretation')]:
                val=item.get(key)
                if isinstance(val,dict):candidates.append({'candidate_id':item['item_id']+'-'+origin,'origin_flags':[origin,'SILVER_CANDIDATE'],'candidate':val,'truth_status':'UNREVIEWED'})
        # Full candidate inventory, not only disagreement list. It remains Silver.
        additional+=len(candidates)
        context={'benchmark_paper_id':bid,'paper_id':pid,'candidate_visibility_default':'HIDDEN_BLIND_SOURCE_FIRST','a_available':any('A_ONLY' in c['origin_flags'] for c in candidates),'g_available':any('G_ONLY' in c['origin_flags'] for c in candidates),'union_candidate_inventory':candidates,'semantic_alignment':pair,'review_accelerators':aids,'candidate_items_are_gold':False}
        atomic_write(package/'candidate_context.json',context)
        atomic_write(package/'manifest.json',{'benchmark_paper_id':bid,'paper_id':pid,'status':'AWAITING_HUMAN_ANNOTATION','source_linked':True,'created_at':now(),'source_coverage_review_complete':False,'candidate_count':len(candidates),'gold_experiment_count':0,'claim_count':0,'evidence_count':0,'freeze_eligible':False})
        checklist={'complete_source_inventory_reviewed':False,'source_coverage_review_complete':False,'objects_bound':False,'granularity_resolved':False,'critical_claims_evidenced':False,'independent_reviews_complete':False,'adjudication_complete':False,'validator_passed':False}
        atomic_write(package/'review_checklist.json',checklist)
        for role in ('ANNOTATOR_A','ANNOTATOR_B','ADJUDICATOR'):
            path=package/'annotations'/f'{role}.json'
            if not path.exists():atomic_write(path,{'benchmark_paper_id':bid,'paper_id':pid,'role':role,'annotator_id':'UNASSIGNED','annotation_tier':'UNANNOTATED','review_state':'AWAITING_HUMAN_ANNOTATION','revision':0,'source_coverage_review_complete':False,'experiments':[],'claims':[],'evidence':[],'decisions':[],'history':[],'created_at':now(),'updated_at':now()})
    atomic_write(GOLD_ROOT/'build_summary.json',{'packages':10,'fixed_mapping_valid':True,'wave2_unresolved_imported':imported,'union_candidate_items':additional,'gold_records_created':0,'status':'AWAITING_HUMAN_ANNOTATION'})
if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--no-resume',action='store_true');args=parser.parse_args();main(not args.no_resume)
